module.exports=function createTalhaRunnerRuntime(ctx){
const app=ctx.app,ScriptLanguage=ctx.ScriptLanguage,UndoModes=ctx.UndoModes,core=ctx.core,MAX_HISTORY=20,FAVORITES_KEY="talhaRunnerV2Favorites",SEEN_KEY="talhaRunnerSeenUpdate",SKIP_KEY="talhaRunnerSkippedUpdate";let history=[],listeners=[],latest=null;
function on(el,e,h){if(!el)return;el.addEventListener(e,h);listeners.push([el,e,h]);}function el(id){return document.getElementById(id);}function store(k,v){try{localStorage.setItem(k,v);}catch(e){}}function load(k){try{return localStorage.getItem(k)||"";}catch(e){return"";}}
function initialize(){const code=el("codeInput"),run=el("runButton"),clear=el("clearButton"),clearAfter=el("clearAfterRun"),status=el("statusText"),historyBtn=el("historyButton"),saveBtn=el("saveFavoriteButton"),favBtn=el("favoritesButton"),updateBtn=el("updateButton"),version=el("versionText"),updateStatus=el("updateStatus"),bell=el("bellButton"),card=el("notificationCard"),noticeTitle=el("notificationTitle"),noticeSummary=el("notificationSummary"),details=el("detailsButton"),skip=el("skipButton");if(!code||!run)throw new Error("Runner arayüzü bulunamadı");
function setStatus(m){if(status)status.textContent=m;}function refreshVersion(){if(version)version.textContent="V2 • "+core.getRuntimeVersion()+"  |  Core "+core.getCoreVersion();if(updateStatus)updateStatus.textContent="● "+(ctx.runtimeOrigin==="bundled"?"Yerleşik":"Güncel");}refreshVersion();
function addHistory(c){if(c&&history[0]!==c){history.unshift(c);if(history.length>MAX_HISTORY)history.pop();}}function focus(){try{code.focus();}catch(e){}}function restore(){try{if(app.activeWindow&&app.activeWindow.activate)app.activeWindow.activate();}catch(e){}}
function runCode(){const c=code.value;if(!c||!c.replace(/\s/g,""))return setStatus("Kod alanı boş");setStatus("Çalıştırılıyor...");try{app.doScript(c,ScriptLanguage.JAVASCRIPT,undefined,UndoModes.ENTIRE_SCRIPT,"Talha Runner V2");addHistory(c);setStatus("✓ Tamamlandı");if(clearAfter&&clearAfter.checked)code.value="";}catch(e){setStatus("✕ "+(e&&e.message?e.message:String(e)));}finally{restore();}}
function loadFav(){try{const p=JSON.parse(localStorage.getItem(FAVORITES_KEY)||"[]");return Array.isArray(p)?p:[];}catch(e){return[];}}function saveFav(a){localStorage.setItem(FAVORITES_KEY,JSON.stringify(a));}
function saveCurrent(){const c=code.value;if(!c||!c.replace(/\s/g,""))return setStatus("Favoriye kaydedilecek kod yok");const n=prompt("Favori adı:","");if(n===null||!String(n).trim())return;const name=String(n).trim(),a=loadFav();let i=a.findIndex(x=>String(x.name).toLocaleLowerCase()===name.toLocaleLowerCase());if(i>=0){if(!confirm("'"+a[i].name+"' zaten var. Üzerine yazılsın mı?"))return;a[i]={name,code:c};}else a.push({name,code:c});saveFav(a);setStatus("★ Favoriye kaydedildi: "+name);}
function showFav(){let a=loadFav();if(!a.length)return setStatus("Favoriler boş");let m="FAVORİLER\n\n";a.forEach((x,i)=>m+=(i+1)+". "+x.name+"\n");m+="\nNumara = yükle | R3 = yeniden adlandır | S3 = sil";const s=prompt(m,"1");if(s===null)return;const z=String(s).trim(),r=/^R(\d+)$/i.exec(z),d=/^S(\d+)$/i.exec(z);if(r){const i=Number(r[1])-1;if(!a[i])return;const n=prompt("Yeni favori adı:",a[i].name);if(n&&String(n).trim()){a[i].name=String(n).trim();saveFav(a);setStatus("Favori yeniden adlandırıldı");}return;}if(d){const i=Number(d[1])-1;if(a[i]&&confirm("'"+a[i].name+"' favorisi silinsin mi?")){const n=a[i].name;a.splice(i,1);saveFav(a);setStatus("Favori silindi: "+n);}return;}if(/^\d+$/.test(z)&&a[Number(z)-1]){const x=a[Number(z)-1];code.value=x.code;setStatus("★ Favoriden yüklendi: "+x.name);focus();}}
function showHistory(){if(!history.length)return setStatus("Geçmiş boş");let m="SON ÇALIŞTIRILAN KODLAR\n\n";history.forEach((x,i)=>m+=(i+1)+". "+x.replace(/[\r\n]/g," ").slice(0,60)+"\n");const s=prompt(m,"1");if(s!==null&&/^\d+$/.test(String(s).trim())&&history[Number(s)-1]!==undefined){code.value=history[Number(s)-1];focus();}}
function renderNotice(info){latest=info;if(!info.available){bell.classList.remove("unread");if(card)card.classList.remove("visible");if(updateStatus)updateStatus.textContent="● Güncel";return;}if(load(SKIP_KEY)===info.version){bell.classList.remove("unread");return;}if(load(SEEN_KEY)!==info.version)bell.classList.add("unread");if(noticeTitle)noticeTitle.textContent="Yeni sürüm: "+info.version;if(noticeSummary)noticeSummary.textContent=info.summary||"Yeni sürüm mevcut.";}
async function silentCheck(){try{renderNotice(await core.checkForUpdate());}catch(e){}}
function openBell(){if(!latest||!latest.available){setStatus("Yeni bildirim yok");return;}store(SEEN_KEY,latest.version);bell.classList.remove("unread");card.classList.toggle("visible");}
function showDetails(){if(!latest)return;let m=(latest.title||("TALHA RUNNER "+latest.version))+"\n\n"+(latest.summary||"")+"\n";if(latest.notes&&latest.notes.length)m+="\nYENİLİKLER / DÜZELTMELER\n• "+latest.notes.join("\n• ");if(latest.history&&latest.history.length){m+="\n\nSÜRÜM GEÇMİŞİ";latest.history.forEach(x=>{m+="\n\n"+x.version+(x.title?" — "+x.title:"");if(x.notes&&x.notes.length)m+="\n• "+x.notes.join("\n• ");});}const p=core.getPreviousVersion();m+="\n\nKurulu runtime: "+core.getRuntimeVersion()+"\nCore: "+core.getCoreVersion()+(p?"\nÖnceki sürüm: "+p:"");alert(m);}
function skipVersion(){if(!latest||!latest.available)return;store(SKIP_KEY,latest.version);store(SEEN_KEY,latest.version);bell.classList.remove("unread");card.classList.remove("visible");setStatus("Bu sürüm atlandı: "+latest.version);}
async function update(){setStatus("Güncelleme kontrol ediliyor...");updateBtn.disabled=true;try{const info=await core.checkForUpdate();if(!info.available){setStatus("✓ Zaten güncel: "+core.getRuntimeVersion());return;}setStatus("İndiriliyor ve doğrulanıyor...");const r=await core.checkAndInstallUpdate();if(r.updated){store(SEEN_KEY,r.version);store(SKIP_KEY,"");setStatus("✓ Güncellendi: "+r.version);}}catch(e){setStatus("✕ Güncelleme başarısız: "+(e.message||e));}finally{updateBtn.disabled=false;}}
function rollback(){const p=core.getPreviousVersion();if(!p)return setStatus("Önceki sürüm yok");if(!confirm(p+" sürümüne geri dönülsün mü?"))return;try{const current=core.getRuntimeVersion(),r=core.rollbackToPrevious();store(SKIP_KEY,current);store(SEEN_KEY,current);setStatus("✓ Geri dönüldü: "+r.version);}catch(e){setStatus("✕ Geri dönüş başarısız: "+(e.message||e));}}
if(updateBtn){updateBtn.textContent="Güncelle";}on(run,"click",runCode);on(clear,"click",()=>{code.value="";setStatus("Hazır");focus();});on(code,"keydown",e=>{if(e.ctrlKey&&e.key==="Enter"){e.preventDefault();runCode();}});on(saveBtn,"click",saveCurrent);on(favBtn,"click",showFav);on(historyBtn,"click",showHistory);on(updateBtn,"click",update);on(bell,"click",openBell);on(details,"click",showDetails);on(skip,"click",skipVersion);if(version){version.title="Sürüm bilgisi / önceki sürüme dön";on(version,"click",()=>{const p=core.getPreviousVersion();if(p)rollback();else showDetails();});}setStatus("Hazır");setTimeout(silentCheck,800);}
function dispose(){listeners.forEach(x=>{try{x[0].removeEventListener(x[1],x[2]);}catch(e){}});listeners=[];}return{initialize,dispose};};
